635	+class _InsertionModalBody extends StatefulWidget {
636	+  const _InsertionModalBody();
637	+
638	+  @override
639	+  State<_InsertionModalBody> createState() => _InsertionModalBodyState();
640	+}
641	+
642	+class _InsertionModalBodyState extends State<_InsertionModalBody> {
643	+  final _textController = TextEditingController();
644	+
645	+  /// Tracks the previously-seen `activeTab` so the listener can tell a
646	+  /// genuine tab switch apart from the many other `TextEntryIdle`
647	+  /// emissions a keystroke produces (`updateText` also emits `Idle`) —
648	+  /// initialized from the cubit's own current state so the very first
649	+  /// comparison (before any emission the listener sees) is still correct.
650	+  late CaptureTab _lastAnnouncedTab;
651	+
652	+  @override
653	+  void initState() {
654	+    super.initState();
655	+    _lastAnnouncedTab = context.read<TextEntryCubit>().state.activeTab;
656	+  }
657	+
658	+  @override
659	+  void dispose() {
660	+    _textController.dispose();
661	+    super.dispose();
662	+  }
663	+
664	+  // Labels for the 3 tabs, shared between the announcement below and
665	+  // `_TabBar`'s own rendering (`_TabBar._tabs`) — kept here too since
666	+  // `selectTab`'s announcement needs the label for whichever tab the
667	+  // user just switched *to*, not the cubit's own (enum-only) state.
668	+  static const _tabLabels = {
669	+    CaptureTab.texto: 'Texto',
670	+    CaptureTab.audio: 'Áudio',
671	+    CaptureTab.foto: 'Foto',
672	+  };
673	+
674	+  // Mirrors `account_settings_screen.dart`'s own `_announce` — VoiceOver
675	+  // (this app is iOS-only) doesn't reliably treat a live-region subtree
676	+  // update as an announcement on its own, so every state change this
677	+  // story introduces — saving, success, failure, and a tab switch — is
678	+  // spoken explicitly here instead (Acceptance Criteria: "no
679	+  // color/animation alone").
680	+  Future<void> _announce(String message) async {
681	+    if (!mounted) {
682	+      return;
683	+    }
684	+    await SemanticsService.sendAnnouncement(
685	+      View.of(context),
686	+      message,
687	+      TextDirection.ltr,
688	+    );
689	+  }
690	+
691	+  @override
692	+  Widget build(BuildContext context) {
693	+    return BlocConsumer<TextEntryCubit, TextEntryState>(
694	+      listener: (context, state) {
695	+        // Review finding: a tab switch (re-emitted as `TextEntryIdle`,
696	+        // same as every keystroke) previously went unannounced —
697	+        // detected here by comparing against the last tab seen, so a
698	+        // plain keystroke (same `activeTab`) never re-triggers it.
699	+        if (state.activeTab != _lastAnnouncedTab) {
700	+          _lastAnnouncedTab = state.activeTab;
701	+          _announce('Aba ${_tabLabels[state.activeTab]} selecionada');
702	+        }
703	+        switch (state) {
704	+          case TextEntrySaved():
705	+            // I/O matrix: "success closes the modal". Announced before
706	+            // popping — review finding: this previously fell through to
707	+            // `break` with no announcement at all.
708	+            _announce('Registro salvo');
709	+            Navigator.of(context).pop();
710	+          case TextEntrySaving():
711	+            _announce('Salvando registro');
712	+          case TextEntryError():
713	+            _announce(state.message);
714	+          case TextEntryIdle():
715	+            break;
716	+        }
717	+      },
718	+      builder: (context, state) {
719	+        final isSaving = state is TextEntrySaving;
720	+        return Container(
721	+          padding: DesignTokens.screenPadding,
722	+          decoration: const BoxDecoration(
723	+            color: DesignTokens.colorSurfaceElevated,
724	+            borderRadius: BorderRadius.vertical(
725	+              top: Radius.circular(DesignTokens.radiusLg),
726	+            ),
727	+            boxShadow: DesignTokens.elevation2,
728	+          ),
729	+          child: Padding(
730	+            // Keeps the Texto field clear of the on-screen keyboard — the
731	+            // sheet is `isScrollControlled: true`, so it already grows to
732	+            // fit; this is the standard companion fix for the keyboard
733	+            // inset itself.
734	+            padding: EdgeInsets.only(
735	+              bottom: MediaQuery.of(context).viewInsets.bottom,
736	+            ),
737	+            child: SafeArea(
738	+              top: false,
739	+              child: Column(
740	+                mainAxisSize: MainAxisSize.min,
741	+                crossAxisAlignment: CrossAxisAlignment.stretch,
742	+                children: [
743	+                  Row(
744	+                    crossAxisAlignment: CrossAxisAlignment.center,
745	+                    children: [
746	+                      Expanded(
747	+                        child: _TabBar(
748	+                          activeTab: state.activeTab,
749	+                          isSaving: isSaving,
750	+                        ),
751	+                      ),
752	+                      const SizedBox(width: DesignTokens.spacingSm),
753	+                      _CloseButton(isSaving: isSaving),
754	+                    ],
755	+                  ),
756	+                  const SizedBox(height: DesignTokens.spacingMd),
757	+                  switch (state.activeTab) {
758	+                    CaptureTab.texto => _TextoTab(
759	+                      controller: _textController,
760	+                      state: state,
761	+                    ),
762	+                    CaptureTab.audio => const _IdleTabPlaceholder(
763	+                      icon: Icons.mic_none,
764	+                      label: 'Áudio chega em breve',
765	+                    ),
766	+                    CaptureTab.foto => const _IdleTabPlaceholder(
767	+                      icon: Icons.photo_camera_outlined,
768	+                      label: 'Foto chega em breve',
769	+                    ),
770	+                  },
771	+                ],
772	+              ),
773	+            ),
774	+          ),
775	+        );
776	+      },
