2662	@@ -0,0 +1,46 @@
2663	+import 'dart:io';
2664	+
2665	+import 'package:path_provider_platform_interface/path_provider_platform_interface.dart';
2666	+
2667	+/// Stands in for the real `path_provider` plugin wherever
2668	+/// `Hive.initFlutter()` (first exercised by Story 3.1's
2669	+/// `registerEntriesFeature()`, transitively via `hive_ce_flutter`) runs
2670	+/// under `flutter test` — no device/simulator exists yet (AGENTS.md) to
2671	+/// answer `getApplicationDocumentsPath()` for real. Returns a fresh temp
2672	+/// directory per call instead, same "fake the native platform channel"
2673	+/// rationale `bootstrap_integration_test.dart`/`main_test.dart` already
2674	+/// apply to `flutter_secure_storage`.
2675	+///
2676	+/// Review finding: a temp directory created here is real disk state, not
2677	+/// an in-memory fake — without [cleanUp], every test run exercising DI
2678	+/// bootstrap leaks one orphaned folder under the OS temp dir per `setUp()`
2679	+/// call. Callers are expected to hold on to the instance they assign to
2680	+/// `PathProviderPlatform.instance` and call [cleanUp] from their own
2681	+/// `tearDown`.
2682	+class FakePathProviderPlatform extends PathProviderPlatform {
2683	+  final List<Directory> _createdDirectories = [];
2684	+
2685	+  @override
2686	+  Future<String?> getApplicationDocumentsPath() async {
2687	+    final dir = Directory.systemTemp.createTempSync('cerne_test_hive_');
2688	+    _createdDirectories.add(dir);
2689	+    return dir.path;
2690	+  }
2691	+
2692	+  /// Deletes every temp directory this instance created. Safe to call
2693	+  /// even if nothing was ever created, and even if a directory was
2694	+  /// already removed by something else.
2695	+  Future<void> cleanUp() async {
2696	+    for (final dir in _createdDirectories) {
2697	+      try {
2698	+        if (await dir.exists()) {
2699	+          await dir.delete(recursive: true);
2700	+        }
2701	+      } catch (_) {
2702	+        // Best-effort cleanup — a leftover temp folder is a minor local
2703	+        // annoyance, never a reason to fail the test that asked for it.
2704	+      }
2705	+    }
2706	+    _createdDirectories.clear();
2707	+  }
2708	+}
